"use client";

import { useSearchParams } from "next/navigation";
import { BadgeIndianRupee, CheckCircle2 } from "lucide-react";

export default function SuccessPageContent() {
  const params = useSearchParams();

  const message = params.get("message") || "Payment Successful";
  const paymentId = params.get("payment_id");
  const orderId = params.get("order_id");

  return (
    <div className="h-screen flex flex-col items-center justify-center px-4 text-center">
      <div className="border w-16 h-16 flex items-center justify-center rounded-full border-[#b79464]">
        <CheckCircle2 className="size-8 text-[#b79464]" />
      </div>

      <h1 className="mt-6 text-2xl font-semibold text-green-600">
        {message}
      </h1>

      {paymentId && (
        <p className="mt-2 text-gray-600">
          Payment ID: <span className="font-semibold">{paymentId}</span>
        </p>
      )}

      {orderId && (
        <p className="mt-1 text-gray-600">
          Order ID: <span className="font-semibold">{orderId}</span>
        </p>
      )}
      <div className="flex items-center flex-col sm:flex-row gap-4">
      <a
        href="/"
        className="mt-6 inline-block px-6 py-2 bg-[#b79464] text-white rounded-lg  transition-all"
      >
        Go to Home
      </a>
            <a
        href="/"
        className="mt-6 inline-block px-6 py-2 border  border-[#b79464] text-black rounded-lg"
      >
        Click to see your Orders
      </a>
      </div>
    </div>
  );
}
